"""
Caelestia System Customization Hook.
Preserves user Material 3 variant (e.g. Expressive, Vibrant, Rainbow) across wallpaper changes.
"""
import sys

class _CaelestiaWallpaperHook:
    def find_spec(self, fullname, path, target=None):
        if fullname == "caelestia.utils.wallpaper":
            sys.meta_path.remove(self)
            try:
                import importlib.util
                spec = importlib.util.find_spec(fullname)
                if spec and spec.loader:
                    orig_exec = spec.loader.exec_module
                    def patched_exec(module):
                        orig_exec(module)
                        if hasattr(module, "get_smart_opts"):
                            orig_opts = module.get_smart_opts
                            def smart_opts_preserve(wall, cache):
                                opts = orig_opts(wall, cache)
                                try:
                                    from caelestia.utils.paths import get_config
                                    cfg = get_config().get("wallpaper", {})
                                    if not cfg.get("preserveVariant", True):
                                        return opts

                                    from caelestia.utils.scheme import get_scheme
                                    s = get_scheme()
                                    if s and getattr(s, "variant", None):
                                        opts["variant"] = s.variant
                                except Exception:
                                    pass
                                return opts
                            module.get_smart_opts = smart_opts_preserve
                    spec.loader.exec_module = patched_exec
                return spec
            finally:
                sys.meta_path.insert(0, self)
        return None

sys.meta_path.insert(0, _CaelestiaWallpaperHook())
